rawOutputs:
{
  "queries": [
    {
      "title": "Genes with at least 50 ADPKD literature references",
      "expr": {
        "kind": "condition",
        "field": "Node filters::Literature evidence::ADPKD literature evidence",
        "op": "BETWEEN",
        "min": 50,
        "max": 911
      }
    }
  ]
}

{
  "queries": [
    {
      "title": "Genes with log2FC >= 2 in large cysts",
      "expr": {
        "kind": "condition",
        "field": "Node filters::Bulk TX data::Large cysts [log2FC]",
        "op": "BETWEEN",
        "min": 2,
        "max": 8.76696610069931
      }
    }
  ]
}

{
  "queries": [
    {
      "title": "Medium cyst log2FC extremes",
      "expr": {
        "kind": "condition",
        "field": "Node filters::Bulk TX data::Medium cysts [log2FC]",
        "op": "LT_OR_GT",
        "lt": -1,
        "gt": 2
      }
    }
  ]
}

{
  "queries": [
    {
      "title": "Protein-protein interaction edges",
      "expr": {
        "kind": "condition",
        "field": "Edge filters::Physical interactions::Protein-protein interaction",
        "op": "IS_TRUE"
      }
    }
  ]
}

{
  "queries": [
    {
      "title": "Protein-protein interaction edges with at least 5 ADPKD literature associations",
      "expr": {
        "kind": "binary",
        "bop": "AND",
