          "kind": "condition",
          "field": "Edge filters::Physical interactions::Protein-protein interaction",
          "op": "IS_TRUE"
        },
        "right": {
          "kind": "condition",
          "field": "Edge filters::Literature associations::in ADPKD",
          "op": "BETWEEN",
          "min": 5,
          "max": 726
        }
      }
    }
  ]
}

{
  "queries": [
    {
      "title": "High biomarker scores and literature associations",
