          "kind": "condition",
          "field": "Node filters::Biomarker annotation::ADPKD biomarker score",
          "op": "BETWEEN",
          "min": 50,
          "max": 288
        },
        "right": {
          "kind": "condition",
          "field": "Edge filters::Literature associations::in ADPKD",
          "op": "BETWEEN",
